(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sc"] = {"ui":{"skip":"Brinca a su cuntenutu","back":"← Torra a AI-gile","lang.button":"Limba: {name}","lang.dialog":"Sèbera una limba","lang.search":"Chirca limbas","lang.none":"Peruna limba currispondet","lang.notYet":"{name} no est ancora tradùida","theme.aria":"Càmbia intre tema craru e tema iscuru","theme.toLight":"Passa a su tema craru","theme.toDark":"Passa a su tema iscuru","index.title":"AI-gile: s'iscuadra tua de isvilupu IA, in una tàula sola","index.description":"AI-gile est una tàula kanban pro iscuadras de programmatzione cun IA. Issas traballant mentras tue dormis; a tie ti abarrat una pila curtza de cosas de detzidere, de proare e de atzetare.","hero.logoAlt":"Icona de sa tàula AI-gile","hero.h1.html":"S'iscuadra tua de isvilupu IA, in una&nbsp;tàula.","hero.alpha":"🐣 Pre-alfa serrada","hero.alphaTitle":"Galu a su printzipiu e no finidu: gràtzias de lu proare!","hero.lede":"Issas costruint mentras tue dormis. Tue ti sullevas cun una pila curtza: carchi pregonta, carchi cosa de proare, unu diamante birde-lillas o duos. Un'incarcada, atzetas, e torras a su caffè.","dl.windows":"App pro Windows","dl.browser":"Allughe·lu in su navigadore","dl.soon":"Prestu","dl.notify":"🔔 Avisa·mi cando abbèrrit","dl.notifySmall":"Alfa o beta","hero.secondary":"Agile, ma s'iscuadra no tenet bisòngiu de su caffè de su stand-up. (Ma lu faghet su matessi.)","pitch.h2":"AI-gile in cantu paràulas cheres","pitch.lede":"Sèbera una longària, dae una paràula a 144. Ogni longària est una descritzione sua, iscrita pro cussa mannària. Tira su cursore o imprea sas fritzas.","pitch.rangeLabel":"Longària in paràulas","pitch.dice":"🎲 un'àtera versione","pitch.words.one":"{n} paràula","pitch.words.other":"{n} paràulas","pitch.letters.one":"{n} lìtera","pitch.letters.other":"{n} lìteras","pitch.chars.one":"{n} caràtere","pitch.chars.other":"{n} caràteres","count.line.html.one":"{n} carta in sa tàula como etotu","count.line.html.other":"{n} cartas in sa tàula como etotu","features.aria":"Ite faghet","f.pile.h":"Una pila sola pro tie","f.pile.html":"<b>Pro tie</b> regollit totu su chi t'istat abetende, de totu sos progetos: pregontas, cosas de proare, traballos chi podet fàghere isceti una persone. Sa coda tua narat ite benit a pustis e cantu tardat.","f.sleep.h":"Iscuadras chi traballant mentras tue dormis","f.sleep.p":"Ogni progetu tenet unu cabu e un'iscuadra de agentes IA. Lassa unu cummentu in una carta, s'iscuadra si sèberat, faghet su traballu e si lu torrat cun passos chi sighit fintzas una persone istraca.","f.tester.h":"Su proadore IA controllat primu","f.tester.p":"Innantis chi bessat a tie, su proadore sighit sos passos in una copia de s'app e mustrat ite at bidu, cun una catura de ischermu. Isfògia sas chi sunt passadas e atzeta cun un'incarcada.","f.proof.h":"Provas, no promissas","f.proof.p":"Ogni cunsigna mustrat ite est mudadu: sos archìvios, sa diferèntzia, sas caturas de ischermu. Nudda de abèrrere ogni app pro ischire si est fata.","f.chat.h":"Chistiona cun sos cabos tuos","f.chat.p":"Una barra a modu de Discord: un'icona pro ogni progetu, diamantes birde-lillas pro su chi tenet bisòngiu de tie. Imbia un'idea a unu cabu; issu la faghet cartas e pranu, cun unu butone ✅ Go.","f.tidy.h":"Si mantenet in òrdine","f.tidy.p":"Sas cartas parentes si fundent in una, sos tìtulos imbroglios s'acontzant, e unu controllu de sos token mantenet su còdighe lestru. Menus cosas intre sas cales andare, menus de pensare.","f.private.h":"Tua, in su computer tuo","f.private.li1":"Sa tàula girat in su computer tuo e rispondet isceti a tie.","f.private.li2":"Sos messàgios privados intre sas persones sunt cifrados dae unu cabu a s'àteru.","f.private.li3":"Peruna crèsia, peruna ispia, perunu cookie.","f.lang.h":"In sa limba tua","f.lang.p":"Prus de 120 limbas, dae s'olandesu, su galesu e su giaponesu a su de sos piratas, de Yoda e su clingon, cun unu passàgiu lestru a s'inglesu pro sas paràulas de sos isvilupadores.","tl.aria":"Lìnia de su tempus dae sa prima faedda a sa mapa de su caminu","tl.h2":"Dae sa prima faedda a su chi benit","tl.lede":"Datas e oras beras, in su fusu oràriu tuo. Dae oe in antis b'est su pranu, chene datas promìtidas.","tl.today":"Oe","tl.planned":"pranadu","tl.cards.one":"{n} carta","tl.cards.other":"{n} cartas","join.h2":"Vene puru tue","join.lede":"AI-gile lu costruit una persone minore e una caterva de agentes pazientes. Pro como est privadu, in una alfa serrada cun amigos. Cheres proare cando s'abbèrrit?","join.btn":"Registra s'interessu","join.small":"Ti iscrimus a posta, nudda de àteru","footer.tag":"AI-gile. Peruna ispia, perunu cookie, perunu caffè de stand-up.","footer.licence":"Lissèntzia pro impresas","footer.status":"Istadu","form.sending":"Imbiende…","form.failed":"No at funtzionadu: torra a proare a pustis.","form.offline":"No amus lòmpidu a AI-gile: torra a proare a pustis.","interest.title":"AI-gile: avisa·mi cando s'alfa abbèrrit","interest.description":"Lassa sa posta eletrònica tua pro ischire cando s'alfa o sa beta serrada de AI-gile abbèrrit.","interest.h1":"🔔 Avisa·mi cando abbèrrit","interest.lede":"AI-gile est in pre-alfa serrada. Lassa sa posta eletrònica tua e ti iscrimus una borta isceti, cando b'at logu pro tie.","interest.email":"Sa posta eletrònica tua","interest.which":"Ite proa?","interest.alpha":"Alfa serrada: a su printzipiu, aspra, cun medas mudàntzias","interest.beta":"Beta: prus istàbile, prus a tardu","interest.both":"Cale chi siat, sa chi benit primu","interest.submit":"Pone·mi in sa lista","interest.thanks":"Gràtzias! Ses in sa lista.","interest.kept":"Si mantenet isceti sa posta eletrònica tua e sa proa sèberada, pro custa lista isceti. Peruna newsletter, peruna ispia.","licence.title":"AI-gile: lissèntzia pro impresas","licence.description":"Impreas AI-gile in s'impresa tua? Pedi una lissèntzia pro impresas de badas.","licence.h1":"📜 Lissèntzia pro impresas","licence.lede":"Impreas AI-gile a su traballu? Nara·nos chie ses e ite faghes. Si faghet unu pagu de bene, sa lissèntzia est de badas.","licence.company":"Impresa","licence.website":"Situ web","licence.what":"Ite faghes","licence.how":"Comente agiudat su mundu","licence.email":"Posta eletrònica","licence.submit":"Imbia sa dimanda","licence.thanks":"Gràtzias! Ti rispondimus a posta.","status.title":"Istadu de AI-gile","status.h1":"Istadu de AI-gile","status.quiet":"Totu in paghe","status.checking":"Controllende…","status.offline":"Como no resessimus a lòmpere a su servìtziu de s'istadu (torramus a proare)","status.updated":"agiornadu {ago}","status.justNow":"como etotu","status.min":"{n} min a como","status.hours":"{n} h a como","status.days":"{n} d a como"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegadu."]},{"n":2,"texts":["Kanban robòticu.","Agentes, organizados.","Ideas, costruidas."]},{"n":3,"texts":["Kanban pro robots.","Ideas diventant funtziones.","Kanban pro agentes IA."]},{"n":5,"texts":["Una tàula kanban guvernada dae agentes.","Tue iscries cartas. Sos agentes costruint.","De badas, locale, proadu, mattu."]},{"n":8,"texts":["Una tàula kanban de badas inue traballant agentes IA.","Iscrie un'idea. Sos agentes la costruint. Tue atzetas.","Agile pro una persone e medas robots pazientes."]},{"n":13,"texts":["Una tàula kanban in su computer tuo, inue sos agentes IA leant sas cartas.","Iscrie un'idea. Un'iscuadra de agentes la costruit. Unu proadore la controllat.","De badas, chene crèsias nen ispias: una tàula, carchi robot e tue a cumandu."]},{"n":21,"texts":["AI-gile est una tàula kanban pro traballare cun agentes IA chi programmant. Issos leant sas cartas; tue las proas e las atzetas.","Ogni progetu tenet unu cabu e un'iscuadra de agentes IA. Lassa unu cummentu in cale chi siat carta e s'iscuadra si ponet a traballare.","Una lista personale de cosas de fàghere, de badas, chi girat in su computer tuo. Sos traballadores sunt robots. Chie narat eja ses tue."]},{"n":34,"texts":["Pones ideas in una tàula. Un'iscuadra de agentes IA las faghet funtziones chi andant, las proat e si las torrat cun passos de proare. Nudda est fatu fintzas a cando tue dis chi est fatu.","AI-gile est una tàula kanban fata in domo, chi Rich at costruidu cun meda agiudu dae sos agentes chi como guvernat issa. Est de badas, girat in su computer tuo e si dat a sos amigos, no si bendet.","Pensa a una tàula kanban normale, cun colunnas dae Backlog a Fatu, ma cun sas cartas leadas dae agentes IA. Issos contant ite est faghende, pregontant cando s'imbrogliant e abetant sempre su bonu tuo."]},{"n":55,"texts":["AI-gile est una tàula kanban inue s'iscuadra est fata de agentes IA. Ogni progetu tenet unu cabu chi pranat su traballu e agiudantes chi lu costruint. Cando una funtzione est pronta, unu proadore IA la proat e faghet una catura de ischermu, e a pustis lòmpet a sa pila tua. La atzetas, o lassas unu cummentu e issos la torrant a fàghere.","Est nàschida comente manera de una persone de sighire medas sessiones de programmatzione cun IA a una borta, e est creschida in una tàula beru. Girat in su computer tuo, no tenet bisòngiu de crèsia e no tenet ispias. Est de badas pro sos amigos e pro chie est curiosu. Est ancora a mesu, duncas isetta·ti ispigos aspros e carchi surpresa.","Custa est sa versione sinchera. Sas ideas las depes ancora tènnere tue, e sos resultados los depes ancora controllare tue. Ite faghet AI-gile est totu su chi b'at in mesu: mantenet sas cartas in òrdine, sèberat s'agente giustu cando cummentas, mustrat propriu ite est mudadu e regollit totu in una pila curtza pro tie."]},{"n":89,"texts":["AI-gile est una tàula kanban de badas chi faghes girare in su computer tuo etotu. In logu de persones, ogni progetu tenet un'iscuadra de agentes IA: unu cabu chi faghet de sas ideas tuas cartas e unu pranu, e agiudantes chi leant sas cartas segundu sa prioridade. Cando carchi cosa est costruida, unu proadore IA sighit sos passos de proa e ti mustrat ite at bidu. A pustis abetat in una pila sola chi si narat Pro tie. La atzetas, o lassas unu cummentu e s'iscuadra torrat a proare. Nudda lòmpet mai a Fatu chene tie.","Carchi cosa chi forsis no ti isetas. Una guardia de note mantenet piena sa colunna De fàghere mentras tue dormis, sèberende cartas chi no cheren peruna risposta dae tie. Unu contadore de token mustrat cantu sos agentes ant impreadu oe e custa chida, e su Modu chene token lis narat de non ispèndere. Ti podes iscriere cun sos amigos, e sos messàgios privados sunt cifrados dae unu cabu a s'àteru. Sa tàula faeddat de a pagu 120 limbas, comprendende s'olandesu, su fiammingu, sos piratas e su clingon. Nudda de custu costat unu soddu, e perunu est chirchende de te lu bèndere.","AI-gile est unu progetu minore e personale, no una sotziedade. Rich cheriat tènnere a ojos medas progetos de programmatzione cun IA chene abèrrere ogni app a los controllare, duncas issu e sos agentes ant fatu una tàula pro custu, e a pustis ant impreadu sa tàula pro costruire su restu. Est in pre-alfa serrada, chi cheret nàrrere chi funtzionat, in prevalèntzia, pro unu pugnu de amigos. Non b'at pàgina de prètzios, newsletter nen pranu de crèschida. Si ti paret ùtile, podes pedire de lu proare cando s'abbèrrit unu pagu de prus."]},{"n":144,"texts":["AI-gile est una tàula kanban pro una persone e una caterva de agentes IA. Girat in su computer tuo e est de badas dae sa conca a sos pes. Agiunghes progetos, e ogni progetu tenet unu cabu e un'iscuadra pitica. Chistionas cun su cabu, unu pagu comente in Discord, e li contas un'idea; issu la faghet cartas e pranu, e a pustis abetat chi tue incarches Go. S'iscuadra faghet sas cartas segundu sa prioridade, cun una lìnia de cumandu simple fata pro sos modellos de limba. Innantis chi carchi cosa torret a tie, unu proadore IA sighit sos passos in una copia de s'app e allegat una catura de ischermu. Su traballu finidu lòmpet a sa pila tua cun sos archìvios mudados e sa diferèntzia. Lu atzetas, o lassas unu cummentu e s'iscuadra si sèberat e torrat a proare. Isceti tue podes mòvere una carta a Fatu.","Una die cun AI-gile, in sustàntzia. A sero lassas carchi cummentu: custu butone est in su logu isballiadu, cussa lista depet èssere ordinada, podimus tènnere unu tema iscuru. Ti ch'andas a durmire. Sos agentes leggint sos cummentos, faghent sas mudàntzias, las proant e ti las torrant. Si De fàghere si mutit, sa guardia de note lu piticat dae su backlog cun cartas chi no cheren peruna risposta dae tie. Sa manzanu b'at una pila curtza sola: duas pregontas e carchi cosa de proare, cada una cun passos chi sighit fintzas una persone dormida e una catura de ischermu chi mustrat chi funtzionat. Passas, atzetas sas bonas e torras su restu. Unu contadore de token mustrat ite b'est andadu, e su Modu chene token est pro sas chidas magras. Pustis faghes colatzione, e in custu sos agentes no podent ancora agiudare.","In primu, ite no est AI-gile. No est una startup, no est in vendita e nemos regollit sos datos tuos. Est una tàula de badas chi girat in su computer tuo, chene crèsias, ispias nen cookie. Ite est: unu logu sulidu inue bìdere totu sos progetos de programmatzione cun IA in una borta, cun un'iscuadra de agentes chi faghet sas cartas e tue chi detzides. Fundet sas cartas parentes, acontzat sos tìtulos imbroglios e istat in atentu a comente abarrat lestru su còdighe. Faeddat de a pagu 120 limbas, dae s'olandesu e su fiammingu a sos piratas e su clingon. Sos amigos si podent iscriere intre issos, in privadu e cifradu. L'ant costruida Rich e una caterva de agentes pazientes, mescamente impreende·la issa matessi. Est in pre-alfa serrada, duncas in logos est aspra. Si ti paret divertente, pedi cun bona manera e forsis intras in antis."]}],"quips":{"1":"Una paràula. Curaggiosa. Forsis tropu curaggiosa.","3":"Tres paràulas. Giai prus sinceras de sa majoria de sas pàginas de produtu.","8":"Oto paràulas. Ancora prus curtzas de unu stand-up.","21":"Sas longarias sunt story points, a proposìtu. Ma certu.","55":"Cincuantacincu paràulas. Duas cartas si sunt finidas mentras lèghias.","144":"Custa est sa longa. Non b'at 233. Sos agentes ch'ant a durmire."}},"timeline":{"first-idea.name":"Sa prima idea","first-idea.line":"Sa prima faedda, innantis chi esistereret perunu còdighe.","first-board.name":"Sa prima tàula","first-board.line":"Una tàula chi sighit sa costrutzione sua matessi: cartas, colunnas, trìbulu e lassa, progetos.","team-roles.name":"Iscuadra e roles","team-roles.line":"Profilos de agentes, modellos de iscuadra, ispàtzios e chie faghet ite.","install.name":"Installatzione e versiones","install.line":"Unu zip chi unu amigu podet installare, agiornamentos a solu, canales e torrada a segus.","usage-saver.name":"Impreu a lestru","usage-saver.line":"Mesurare ite costant sas aviadas, mantènnere su còdighe lestru, sarvare su lìmite.","friends.name":"Amigos e cumpartzidura","friends.line":"MP privados, unu relay cifradu, invitos, roles e progetos cumpartzidos.","languages.name":"Limbas","languages.line":"Ònnia testu de ischermu in unu documentu de limba, cun s'olandesu e su fiammingu primos.","ai-tester.name":"Proadore IA","ai-tester.line":"Unu proadore controllat ònnia cunsigna primu e mustrat ite at bidu.","website.name":"Su situ web","website.line":"aigile.lol, su teaser e custa lìnia de su tempus.","streaming.name":"Chat e streaming","streaming.line":"Discord, Twitch, OBS, modu streamer, GIF e emoji.","no-ai.name":"Edissione chene IA","no-ai.line":"Una tàula pro chie programmat chene IA, e tàulas pùblicas.","night-watch.name":"Guardia de note","night-watch.line":"Unu guardianu e unu Scrum Master mantenent sas iscuadras a traballu mentras tue dormis.","p-more.name":"Totu su restu","p-more.line":"Ideas prus piticas chi abetant su turnu issoro.","p-android.name":"Telèfonu e Android","p-android.line":"Lòmpere a sa tàula dae su telèfonu, e a pustis cun un'app Android nativa.","p-release.name":"Alfa e a pustis","p-release.line":"Alfa serrada, su situ in direta, a pustis sa beta.","p-languages.name":"Prus limbas","p-languages.line":"Prus de chentu limbas e unu modu de immersione pro chie imparat.","p-engines.name":"Prus motores IA","p-engines.line":"Sèbera Claude, Codex o Gemini pro ònnia agente.","p-pro.name":"Pratica professionale","p-pro.line":"Etichetas de risicu, barrieras de unione, cartas de incidente e protetziones.","p-self.name":"Cura de tie","p-self.line":"Modu istracu, remindatziones de cura de tie e 4:20.","p-servers.name":"Servidores e iscala","p-servers.line":"Impostatziones globales de servidore, roles e pranos pro creschere.","p-livestream.name":"Agiuntas de streaming","p-livestream.line":"Chat de Twitch, emoji personalizados e una vista pùblica in direta."}};
